"Agent websites": "Sites des agents",
"Agent when the app opens": "Agent à l’ouverture de l’application",
"Agents act through four kinds of steps: run a command, read a file, write a file, or edit part of a file. Before a command runs or a file changes you see exactly what, and choose Run (or Apply), Skip, or Always allow for the rest of the chat. Reading files in the current folder needs no OK.": "Les agents agissent par quatre types d’étapes : exécuter une commande, lire un fichier, écrire un fichier ou modifier une partie d’un fichier. Avant qu’une commande ne s’exécute ou qu’un fichier ne change, vous voyez exactement ce qui va se passer, et vous choisissez Exécuter (ou Appliquer), Ignorer, ou Toujours autoriser pour la suite du chat. La lecture des fichiers du dossier actuel ne demande aucun accord.",
"Agents can be wrong. Read what they want to run, especially with Working mode or Root, where a command can remove apps or change settings.": "Les agents peuvent se tromper. Lisez ce qu’ils veulent exécuter, surtout avec Mode de fonctionnement ou Root, où une commande peut supprimer des applications ou modifier des paramètres.",
"Agents only see what you send and what their steps return; keys and tokens in output are hidden from them.": "Les agents ne voient que ce que vous envoyez et ce que renvoient leurs étapes ; les clés et jetons présents dans la sortie leur sont masqués.",
