"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store est un client Play Store open source. La détection automatique des versions Play est prévue pour plus tard (elle nécessite une authentification Play anonyme) ; pour l’instant, chaque application est redirigée vers sa page de boutique, en ouvrant Aurora Store s’il est installé.",
"Aurora Store: installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store : installé · Play Store : installé. Appuyez sur une application ci-dessous pour ouvrir sa page dans la boutique.",
