"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind est un serveur MCP : un outil qui donne aux agents IA le contrôle d’un appareil Android via ADB (applications, fichiers, journaux, captures d’écran). Ce n’est pas un chat en soi.",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "DroidMind est installé dans Debian. Lancez-le avec : proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Ajoutez-le à votre agent comme serveur MCP (son adresse s’affiche au démarrage).",
