"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "Chaque agent conserve cela dans son propre fichier, comme le fait sa connexion officielle : deux agents ou plus peuvent donc porter le même serveur et l’un comme l’autre peut l’utiliser. Codex conserve le jeton d’un serveur distant dans une variable d’environnement plutôt que dans son fichier. Non testé avec toutes les versions de tous les outils.",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "Chaque shell garde son propre écran et reste ouvert pendant que vous utilisez d’autres onglets : cd, export et les variables sont conservés d’une commande à l’autre. Redémarrer le shell en lance un nouveau.",
