"Edited": "Modifiés",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "Modifier un APK change son contenu, donc sa signature ne correspond plus. Android ne l’installera pas tant qu’il n’est pas signé à nouveau : utilisez Signer (cette application signe avec une clé qui lui est propre).",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "Modifier un APK change son contenu, donc sa signature ne correspond plus. Android ne l’installera pas tant qu’il n’est pas signé à nouveau ; Signer le fait avec une clé de cette application.",
"Effort": "Effort",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "Le niveau d’effort n’a d’effet que pour les agents dont l’API propose ce réglage (Claude, ChatGPT, Gemini, Grok) ; pour les autres, il est conservé mais sans effet lors d’un chat avec une clé d’API, et aucun ne le transmet à son outil de connexion dans Termux.",
