"It finishes installing itself the first time it opens.": "Il termine son installation à sa première ouverture.",
"It goes back to the version that came with the phone. An older version often cannot use the data of a newer one, so it may lose its data.": "Elle revient à la version fournie avec le téléphone. Une version plus ancienne ne peut souvent pas utiliser les données d’une version plus récente : elle risque donc de perdre ses données.",
"It has no Android build, so it goes into a Debian container inside Termux (several minutes, a few hundred MB). Already installed steps are skipped quickly.": "Il n’a pas de version Android : il s’installe donc dans un conteneur Debian au sein de Termux (plusieurs minutes, quelques centaines de MB). Les étapes déjà installées sont vite ignorées.",
"It is not set any more": "Il n’est plus défini",
"It is removed for the device's user. A system app can be put back with Reinstall.": "Elle est supprimée pour l’utilisateur de l’appareil. Une application système peut être remise avec Réinstaller.",
"It is removed for you. A system app stays on the phone and can be brought back with Reinstall.": "Elle est supprimée pour vous. Une application système reste sur le téléphone et peut être récupérée avec Réinstaller.",
"It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Il est d’abord essayé tel quel ; si Android le refuse, une copie signée avec la clé de cette application est installée.",
"Its settings, accounts and files on the device are deleted.": "Ses paramètres, ses comptes et ses fichiers sur l’appareil sont supprimés.",
"Its settings, accounts, saved games and the files in its own storage are deleted. This cannot be undone.": "Ses paramètres, ses comptes, ses parties enregistrées et les fichiers de son propre stockage sont supprimés. Cette action est irréversible.",
"IzzyOnDroid": "IzzyOnDroid",
"IzzyOnDroid page": "Page IzzyOnDroid",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan exécute des modèles d’IA sur votre ordinateur, gratuitement. Sur l’ordinateur : Jan, Settings, Local API Server : définissez l’hôte sur 0.0.0.0 et démarrez-le, puis saisissez ici l’adresse de l’ordinateur (par ex. http://192.168.1.20:1337/v1). Jan n’existe pas en version Android.",
