"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon est un assistant personnel open source (compétences, voix) qui fonctionne sur un ordinateur avec Node.js et Python. Il n’a pas de version Android et n’est pas un agent de codage : il ne discute donc pas dans ce Terminal.",
