"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Cette application ne demande pas d’écran tactile, de clavier ou de navigation particulier (elle n’a pas d’entrée uses-configuration) : elle s’exécute donc avec ce que ce téléphone possède.",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "Cette application ne déclare aucune fonctionnalité matérielle ou logicielle requise (aucune entrée uses-feature).",
"This app has no activities.": "Cette application n’a aucune activité.",
"This app may not run commands in Termux yet.": "Cette application n’est peut-être pas encore autorisée à exécuter des commandes dans Termux.",
"This app now has its own private ADB key. Tap the mode badge for details.": "Cette application possède désormais sa propre clé ADB privée. Appuyez sur le badge du mode pour plus de détails.",
