"This needs the app build.": "Cela nécessite le build de l’application.",
"This only works with the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); an agent used only with an API key cannot use one here.": "Cela ne fonctionne qu’avec les agents qui se connectent via leur propre outil en ligne de commande dans Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) ; un agent utilisé uniquement avec une clé d’API ne peut pas en utiliser ici.",
"This package carries data files that live outside the APK. Right after the install succeeds they are copied into place.": "Ce package contient des fichiers de données situés en dehors de l’APK. Dès que l’installation réussit, ils sont copiés à leur place.",
