"To make this the default installer, open any APK, choose this app, and tap \"Always\".": "Pour en faire l’installateur par défaut, ouvrez un APK, choisissez cette application et appuyez sur « Toujours ».",
"To search storage for APK, APKS, APKM and XAPK files, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "Pour rechercher des fichiers APK, APKS, APKM et XAPK dans le stockage, cette application a besoin de l’accès à tous les fichiers (ou d’un mode de fonctionnement : ADB, Shizuku ou Root).",
"To search storage for fonts, this app needs All-files access. You can also choose a font file by hand, which needs no access.": "Pour rechercher des polices dans le stockage, cette appli a besoin de l'accès à tous les fichiers. Vous pouvez aussi choisir un fichier de police à la main, sans aucun accès.",
