"v1 is the old signature kept in the META-INF folder. v2, v3 and v3.1 sit in the APK signing block; v3 and v3.1 allow the signing key to be changed later. The base APK is the one read.": "v1 est l’ancienne signature conservée dans le dossier META-INF. v2, v3 et v3.1 se trouvent dans le bloc de signature de l’APK ; v3 et v3.1 permettent de changer la clé de signature plus tard. C’est l’APK de base qui est lu.",
